import { createHash } from "node:crypto";
import { events, requests, controlSchema, lifecycleSchema } from "../../../src/engine/messages/messages";
/** Run with Bun after an intentional wire change; tests independently compare generated bytes. */
export function schemaFiles() {
  const schemas = { requests: { anyOf: Object.values(requests).map(s => s.json) }, events: { anyOf: Object.values(events).map(s => s.json) }, controls: controlSchema.json, lifecycle: lifecycleSchema.json };
  return Object.entries(schemas).map(([family, schema]) => ({ family, text: JSON.stringify({ $schema: "https://json-schema.org/draft/2020-12/schema", ...schema }, null, 2) + "\n" }));
}
if (import.meta.main) for (const { family, text } of schemaFiles()) {
  await Bun.write(new URL(`../../../src/engine/messages/${family}.schema.json`, import.meta.url), text);
  await Bun.write(new URL(`./${family}.sha256`, import.meta.url), createHash("sha256").update(text).digest("hex") + "\n");
}
